import { useMemo, useRef, useState, type RefObject } from "react"
import { useHotkeys } from "react-hotkeys-hook"
import { ChevronDownIcon, ChevronRightIcon } from "lucide-react"

import { EmptyState } from "@/components/mini/states"
import { Badge } from "@/components/ui/badge"
import { ScrollArea } from "@/components/ui/scroll-area"
import { cn } from "@/lib/utils"

import { itemStatus } from "./attention"
import { ageText } from "./format"
import { ItemDetail, StatusLabel } from "./item-detail"
import type { AttentionItem, ItemAction, Tile, Urgency } from "./types"

const GROUPS: Array<{ urgency: Urgency; label: string }> = [
  { urgency: "now", label: "Now" },
  { urgency: "later", label: "Later" },
]

function openedAt(item: AttentionItem): number {
  for (let i = item.timeline.length - 1; i >= 0; i--) {
    const { type, at } = item.timeline[i]
    if (type === "opened" || type === "reopened") return at
  }
  return item.timeline[0]?.at ?? 0
}

function useQueueHotkeys(
  root: RefObject<HTMLElement | null>,
  keys: string,
  run: (event: KeyboardEvent) => void,
  enabled: boolean
) {
  useHotkeys(
    keys,
    (event) => {
      if (event.target instanceof Node && root.current?.contains(event.target))
        run(event)
    },
    { enabled }
  )
}

/**
 * Items that need the user, Now before Later and newest first. Keys, active
 * only while focus is inside the queue and not in a field: j/k move, a
 * acknowledges, s snoozes, r resolves, Enter expands.
 */
export function AttentionQueue({
  items,
  tiles,
  now,
  onAct,
  onOpenTile,
}: {
  items: AttentionItem[]
  tiles: Tile[]
  now: number
  onAct(itemId: string, action: ItemAction): void
  onOpenTile(id: string): void
}) {
  const rootRef = useRef<HTMLDivElement>(null)
  const [selectedId, setSelectedId] = useState<string | null>(null)
  const [expandedId, setExpandedId] = useState<string | null>(null)
  const [snoozeFor, setSnoozeFor] = useState<string | null>(null)

  const groups = useMemo(
    () =>
      GROUPS.map(({ urgency, label }) => ({
        urgency,
        label,
        items: items
          .filter((item) => {
            const status = itemStatus(item, now)
            return (
              item.urgency === urgency &&
              (status === "open" || status === "acknowledged")
            )
          })
          .sort((a, b) => openedAt(b) - openedAt(a)),
      })).filter((group) => group.items.length > 0),
    [items, now]
  )
  const flat = groups.flatMap((group) => group.items)
  const selected = flat.find((item) => item.id === selectedId) ?? flat[0]

  const focusRow = (id: string | undefined) => {
    if (!id) return
    requestAnimationFrame(() => {
      rootRef.current
        ?.querySelector<HTMLElement>(
          `[data-item-id="${CSS.escape(id)}"] [data-queue-row]`
        )
        ?.focus()
    })
  }

  const moveSelection = (to: AttentionItem | undefined) => {
    if (!to) return
    setSelectedId(to.id)
    if (expandedId !== null) setExpandedId(to.id)
    focusRow(to.id)
  }

  const neighbourOf = (item: AttentionItem) => {
    const index = flat.findIndex((candidate) => candidate.id === item.id)
    return flat[index + 1] ?? flat[index - 1]
  }

  const act = (item: AttentionItem, action: ItemAction) => {
    if (action.type !== "acknowledge") {
      const next = neighbourOf(item)
      setSelectedId(next?.id ?? null)
      if (expandedId === item.id) setExpandedId(null)
      focusRow(next?.id)
    }
    setSnoozeFor(null)
    onAct(item.id, action)
  }

  const keysEnabled = flat.length > 0 && snoozeFor === null
  const step = (delta: number) => {
    if (!selected) return
    const index = flat.findIndex((item) => item.id === selected.id)
    moveSelection(flat[Math.min(flat.length - 1, Math.max(0, index + delta))])
  }

  useQueueHotkeys(rootRef, "j", () => step(1), keysEnabled)
  useQueueHotkeys(rootRef, "k", () => step(-1), keysEnabled)
  useQueueHotkeys(
    rootRef,
    "a",
    () => selected && act(selected, { type: "acknowledge" }),
    keysEnabled
  )
  useQueueHotkeys(
    rootRef,
    "r",
    () => selected && act(selected, { type: "resolve" }),
    keysEnabled
  )
  useQueueHotkeys(
    rootRef,
    "s",
    (event) => {
      if (!selected) return
      event.preventDefault()
      setSelectedId(selected.id)
      setExpandedId(selected.id)
      setSnoozeFor(selected.id)
    },
    keysEnabled
  )
  useQueueHotkeys(
    rootRef,
    "enter",
    (event) => {
      if (selected && event.target === rootRef.current) {
        setExpandedId((open) => (open === selected.id ? null : selected.id))
      }
    },
    keysEnabled
  )

  if (flat.length === 0) {
    return (
      <div
        ref={rootRef}
        tabIndex={-1}
        data-queue-root
        className="h-full outline-none"
      >
        <EmptyState title="Nothing needs you" />
      </div>
    )
  }

  return (
    <div
      ref={rootRef}
      tabIndex={-1}
      data-queue-root
      className="flex h-full min-h-0 flex-col outline-none"
    >
      <ScrollArea className="min-h-0 flex-1">
        <div className="flex flex-col gap-3 p-2">
          {groups.map((group) => (
            <section key={group.urgency} aria-label={`${group.label} items`}>
              <h3 className="mb-1 flex items-center gap-1.5 px-1 text-xs font-medium text-muted-foreground">
                {group.label}
                <Badge
                  variant={
                    group.urgency === "now" ? "destructive" : "secondary"
                  }
                >
                  {group.items.length}
                </Badge>
              </h3>
              <ul className="flex flex-col gap-1">
                {group.items.map((item) => {
                  const expanded = expandedId === item.id
                  const isSelected = selected?.id === item.id
                  const tile = tiles.find(
                    (candidate) => candidate.id === item.tileId
                  )
                  return (
                    <li
                      key={item.id}
                      data-item-id={item.id}
                      aria-current={isSelected ? "true" : undefined}
                      className={cn(
                        "rounded-md border bg-card",
                        isSelected &&
                          "border-(--mini-accent) bg-(--mini-accent-soft)"
                      )}
                    >
                      <button
                        type="button"
                        data-queue-row
                        aria-expanded={expanded}
                        onFocus={() => setSelectedId(item.id)}
                        onClick={() => {
                          setSelectedId(item.id)
                          setExpandedId(expanded ? null : item.id)
                        }}
                        className="flex w-full items-start gap-1.5 rounded-md p-2 text-left outline-none focus-visible:ring-3 focus-visible:ring-ring/50"
                      >
                        {expanded ? (
                          <ChevronDownIcon
                            aria-hidden
                            className="mt-0.5 size-3.5 shrink-0"
                          />
                        ) : (
                          <ChevronRightIcon
                            aria-hidden
                            className="mt-0.5 size-3.5 shrink-0"
                          />
                        )}
                        <span className="flex min-w-0 flex-col gap-0.5">
                          <span className="text-sm font-medium">
                            {item.title}
                          </span>
                          <span className="flex flex-wrap items-center gap-x-2 text-xs text-muted-foreground">
                            <StatusLabel status={itemStatus(item, now)} />
                            <span>
                              {ageText(Math.max(0, now - openedAt(item)))} ago
                            </span>
                          </span>
                        </span>
                      </button>
                      {expanded ? (
                        <div className="border-t px-2 py-2">
                          <ItemDetail
                            item={item}
                            tile={tile}
                            now={now}
                            showKeys
                            onAct={(action) => act(item, action)}
                            onOpenTile={onOpenTile}
                            snoozeOpen={snoozeFor === item.id}
                            onSnoozeOpenChange={(open) =>
                              setSnoozeFor(open ? item.id : null)
                            }
                          />
                        </div>
                      ) : null}
                    </li>
                  )
                })}
              </ul>
            </section>
          ))}
        </div>
      </ScrollArea>
    </div>
  )
}

import { addDays, nextMonday, set, startOfDay } from "date-fns"

import type {
  AttentionItem,
  FlagRule,
  ItemAction,
  ItemStatus,
  RuleMemory,
  Tile,
  TimelineEvent,
} from "./types"

const DAY_MS = 86_400_000
const HOUR_MS = 3_600_000

const DECIDING = new Set<TimelineEvent["type"]>([
  "opened",
  "reopened",
  "acknowledged",
  "snoozed",
  "snooze-ended",
  "resolved",
  "cleared",
])

function lastDeciding(item: AttentionItem): TimelineEvent | undefined {
  for (let i = item.timeline.length - 1; i >= 0; i--) {
    if (DECIDING.has(item.timeline[i].type)) return item.timeline[i]
  }
  return undefined
}

function isResolved(item: AttentionItem): boolean {
  const type = lastDeciding(item)?.type
  return type === "resolved" || type === "cleared"
}

/** Derives an item's status from its timeline; status is never stored. */
export function itemStatus(item: AttentionItem, now: number): ItemStatus {
  const last = lastDeciding(item)
  switch (last?.type) {
    case "acknowledged":
      return "acknowledged"
    case "snoozed":
      return (last.until ?? 0) > now ? "snoozed" : "open"
    case "resolved":
    case "cleared":
      return "resolved"
    default:
      return "open"
  }
}

export function isStale(tile: Tile, now: number): boolean {
  return (
    tile.staleAfterMs !== undefined && now - tile.updatedAt > tile.staleAfterMs
  )
}

/** The words for a tile's state; the tile, dialog, cleared text and confirm copy share it. */
export function stateText(tile: Tile): string {
  const unit = tile.unit ?? ""
  switch (tile.kind) {
    case "toggle":
      return tile.on ? (tile.onLabel ?? "On") : (tile.offLabel ?? "Off")
    case "level":
      return tile.on ? `${tile.value ?? 0}${unit}` : (tile.offLabel ?? "Off")
    case "target":
      return `${tile.value ?? 0}${unit} · target ${tile.target ?? 0}${unit}`
    case "sensor":
      return tile.text ?? `${tile.value ?? 0}${unit}`
  }
}

type ActiveRule = {
  id: string
  tileId: string
  title: string
  urgency: FlagRule["urgency"]
  test: (tile: Tile) => boolean
  occurrence?: (tile: Tile) => string
}

function staleRuleId(tileId: string): string {
  return `stale:${tileId}`
}

function withStaleRules(
  rules: FlagRule[],
  tiles: Tile[],
  now: number
): ActiveRule[] {
  const synthetic: ActiveRule[] = tiles
    .filter((tile) => tile.staleOpensItem)
    .map((tile) => ({
      id: staleRuleId(tile.id),
      tileId: tile.id,
      title: `${tile.name} has not reported`,
      urgency: "later",
      test: (t) => isStale(t, now),
    }))
  return [...rules, ...synthetic]
}

function openedAt(item: AttentionItem): number {
  return item.timeline[0]?.at ?? 0
}

function latestItemFor(
  items: AttentionItem[],
  ruleId: string
): AttentionItem | undefined {
  let latest: AttentionItem | undefined
  for (const item of items) {
    if (
      item.ruleId === ruleId &&
      (!latest || openedAt(item) >= openedAt(latest))
    )
      latest = item
  }
  return latest
}

function resolvedAt(item: AttentionItem): number {
  return lastDeciding(item)?.at ?? 0
}

/**
 * Compares each rule's condition with what `previous` remembers and returns the
 * items to add, the events to append to existing items, and the next memory.
 * A flag is an edge: it fires when a condition turns true or its occurrence key
 * changes while true, never on every evaluation.
 */
export function evaluateRules(input: {
  tiles: Tile[]
  items: AttentionItem[]
  rules: FlagRule[]
  previous: RuleMemory
  now: number
  newId: () => string
}): {
  add: AttentionItem[]
  append: Array<{ id: string; events: TimelineEvent[] }>
  memory: RuleMemory
} {
  const { tiles, items, rules, previous, now, newId } = input
  const add: AttentionItem[] = []
  const append: Array<{ id: string; events: TimelineEvent[] }> = []
  const memory: RuleMemory = { ...previous }

  for (const rule of withStaleRules(rules, tiles, now)) {
    const tile = tiles.find((t) => t.id === rule.tileId)
    if (!tile) continue

    const on = rule.test(tile)
    const occurrence = rule.occurrence?.(tile)
    const before = previous[rule.id] ?? { on: false }
    const fires = on && (!before.on || before.occurrence !== occurrence)
    const latest = latestItemFor(items, rule.id)

    if (fires) {
      if (latest && !isResolved(latest)) {
        append.push({
          id: latest.id,
          events: [{ at: now, type: "flagged-again" }],
        })
      } else if (latest && now - resolvedAt(latest) < DAY_MS) {
        append.push({ id: latest.id, events: [{ at: now, type: "reopened" }] })
      } else {
        add.push({
          v: 1,
          id: newId(),
          title: rule.title,
          urgency: rule.urgency,
          tileId: tile.id,
          ruleId: rule.id,
          timeline: [{ at: now, type: "opened" }],
        })
      }
    } else if (before.on && !on && latest && !isResolved(latest)) {
      append.push({
        id: latest.id,
        events: [
          {
            at: now,
            type: "cleared",
            text: `Cleared: ${tile.name} ${stateText(tile).toLowerCase()}`,
          },
        ],
      })
    }

    memory[rule.id] = { on, occurrence }
  }

  return { add, append, memory }
}

/** Returns the events an action adds, or none when the current status does not allow it. */
export function applyItemAction(
  item: AttentionItem,
  action: ItemAction,
  now: number
): TimelineEvent[] {
  const status = itemStatus(item, now)
  switch (action.type) {
    case "acknowledge":
      return status === "open" ? [{ at: now, type: "acknowledged" }] : []
    case "snooze": {
      if (status !== "open" && status !== "acknowledged") return []
      if (action.until <= now) return []
      const note = action.note?.trim()
      return [
        {
          at: now,
          type: "snoozed",
          until: action.until,
          ...(note ? { note } : {}),
        },
      ]
    }
    case "resolve":
      return status === "resolved" ? [] : [{ at: now, type: "resolved" }]
  }
}

/** Appends one `snooze-ended` per elapsed snooze, stamped at the snooze's own end time. */
export function endExpiredSnoozes(
  items: AttentionItem[],
  now: number
): Array<{ id: string; events: TimelineEvent[] }> {
  const ended: Array<{ id: string; events: TimelineEvent[] }> = []
  for (const item of items) {
    const last = lastDeciding(item)
    if (
      last?.type === "snoozed" &&
      last.until !== undefined &&
      last.until <= now
    ) {
      ended.push({
        id: item.id,
        events: [{ at: last.until, type: "snooze-ended" }],
      })
    }
  }
  return ended
}

/**
 * Memory for a fresh mount. A rule counts as already true when its latest item
 * is unresolved or was resolved by hand, so a reload never re-flags something
 * the user dismissed while the condition still held.
 */
export function initialRuleMemory(
  items: AttentionItem[],
  rules: FlagRule[],
  tiles: Tile[]
): RuleMemory {
  const memory: RuleMemory = {}
  for (const rule of withStaleRules(rules, tiles, 0)) {
    const tile = tiles.find((t) => t.id === rule.tileId)
    if (!tile) continue
    const latest = latestItemFor(items, rule.id)
    const on =
      !!latest &&
      (!isResolved(latest) || lastDeciding(latest)?.type === "resolved")
    memory[rule.id] = { on, occurrence: rule.occurrence?.(tile) }
  }
  return memory
}

/** Preset snooze times relative to `now`; "This evening" is omitted after 17:00. */
export function snoozePresets(
  now: number
): Array<{ label: string; until: number }> {
  const today = new Date(now)
  const at = (date: Date, hours: number) =>
    set(date, { hours, minutes: 0, seconds: 0, milliseconds: 0 })
  const presets: Array<{ label: string; until: number }> = [
    { label: "1 hour", until: now + HOUR_MS },
  ]
  if (today.getHours() < 17) {
    presets.push({ label: "This evening", until: at(today, 18).getTime() })
  }
  presets.push(
    {
      label: "Tomorrow morning",
      until: at(addDays(startOfDay(today), 1), 8).getTime(),
    },
    { label: "Next week", until: at(nextMonday(today), 8).getTime() }
  )
  return presets
}

import { Badge } from "@/components/ui/badge"

import type { Summary } from "./types"

/** Summary badges from the app plus one "N need you" count that focuses the queue. */
export function BadgeRow({
  summaries,
  needYouCount,
  onFocusQueue,
  onOpenTile,
}: {
  summaries: Summary[]
  needYouCount: number
  onFocusQueue(): void
  onOpenTile(id: string): void
}) {
  if (summaries.length === 0 && needYouCount === 0) return null
  return (
    <div className="flex flex-wrap items-center gap-1.5">
      {summaries.map((summary) => {
        const { tileId } = summary
        return tileId ? (
          <Badge
            key={summary.id}
            variant="secondary"
            asChild
            className="cursor-pointer"
          >
            <button type="button" onClick={() => onOpenTile(tileId)}>
              {summary.label}
            </button>
          </Badge>
        ) : (
          <Badge key={summary.id} variant="secondary">
            {summary.label}
          </Badge>
        )
      })}
      {needYouCount > 0 ? (
        <Badge variant="destructive" asChild className="cursor-pointer">
          <button type="button" onClick={onFocusQueue}>
            {needYouCount} need you
          </button>
        </Badge>
      ) : null}
    </div>
  )
}

import { useEffect, useRef, useState } from "react"
import {
  ChevronDownIcon,
  ChevronRightIcon,
  PauseIcon,
  RadioIcon,
  TriangleAlertIcon,
  WifiOffIcon,
} from "lucide-react"
import { toast } from "sonner"

import { EmptyState, ErrorState, LoadingState } from "@/components/mini/states"
import { Button } from "@/components/ui/button"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"

import { itemStatus } from "./attention"
import { AttentionQueue } from "./attention-queue"
import { BadgeRow } from "./badge-row"
import { clock } from "./format"
import { TileBoard } from "./tile-board"
import { TileDialog } from "./tile-dialog"
import { activeItemFor } from "./tile-shared"
import type { RefreshState, Summary, Tile } from "./types"
import { useCommandCenter } from "./use-command-center"

const NARROW_PX = 768

export type CommandCenterProps = Parameters<typeof useCommandCenter>[0] & {
  sourceLabel: string
  loadedAt?: number
  summaries?: Summary[]
  status?: "loading" | "ready" | "error"
  error?: Error
  onRetry?: () => void
}

function useNarrow(ref: React.RefObject<HTMLElement | null>): boolean {
  const [narrow, setNarrow] = useState(false)
  useEffect(() => {
    const el = ref.current
    if (!el) return
    const observer = new ResizeObserver(([entry]) =>
      setNarrow(entry.contentRect.width < NARROW_PX)
    )
    observer.observe(el)
    return () => observer.disconnect()
  }, [ref])
  return narrow
}

function RefreshStatus({
  refresh,
  onPause,
  onResume,
}: {
  refresh: RefreshState
  onPause(): void
  onResume(): void
}) {
  if (refresh.state === "none") return null
  const pause = (
    <Tooltip>
      <TooltipTrigger asChild>
        <Button
          size="icon-xs"
          variant="ghost"
          aria-label="Pause refreshing"
          onClick={onPause}
        >
          <PauseIcon aria-hidden />
        </Button>
      </TooltipTrigger>
      <TooltipContent>Pause refreshing</TooltipContent>
    </Tooltip>
  )
  if (refresh.state === "paused") {
    return (
      <span className="flex items-center gap-1.5">
        <PauseIcon aria-hidden className="size-3" />
        Paused
        <Button size="xs" variant="outline" onClick={onResume}>
          Resume
        </Button>
      </span>
    )
  }
  if (refresh.state === "stale") {
    return (
      <span className="flex items-center gap-1.5">
        <WifiOffIcon aria-hidden className="size-3" />
        {refresh.since ? `Stale since ${clock(refresh.since)}` : "Stale"}
        {pause}
      </span>
    )
  }
  return (
    <span className="flex items-center gap-1.5">
      <RadioIcon aria-hidden className="size-3" />
      Live · updated {clock(refresh.at)}
      {pause}
    </span>
  )
}

/**
 * Status tiles in sections beside a queue of items that need the user. Wire it
 * to storage with `onTileUpdate`, `onItemAdd` and `onItemUpdate`; flag rules turn
 * tile conditions into queue items. Renders no AppShell, Toaster or TooltipProvider.
 */
export function CommandCenter(props: CommandCenterProps) {
  const {
    tiles,
    items,
    sourceLabel,
    loadedAt,
    summaries = [],
    status = "ready",
    error,
    onRetry,
    onTileUpdate,
  } = props
  const { now, announcement, refresh, pause, resume, retry, act } =
    useCommandCenter(props)

  const rootRef = useRef<HTMLDivElement>(null)
  const queueRef = useRef<HTMLDivElement>(null)
  const returnFocusRef = useRef<HTMLElement | null>(null)
  const narrow = useNarrow(rootRef)
  const [stripOpen, setStripOpen] = useState(false)
  const [openTileId, setOpenTileId] = useState<string | null>(null)

  const needYou = items.filter((item) => {
    const s = itemStatus(item, now)
    return s === "open" || s === "acknowledged"
  })
  const openTile = tiles.find((tile) => tile.id === openTileId) ?? null
  const linkedItem = openTile
    ? (activeItemFor(items, openTile.id, now) ??
      items
        .filter((item) => item.tileId === openTile.id)
        .sort(
          (a, b) => (b.timeline[0]?.at ?? 0) - (a.timeline[0]?.at ?? 0)
        )[0] ??
      null)
    : null

  const write = (what: string, id: string, patch: Partial<Tile>) => {
    onTileUpdate(id, { ...patch, updatedAt: Date.now() }).catch(
      (cause: unknown) =>
        toast.error(`Couldn't ${what}`, {
          description: cause instanceof Error ? cause.message : String(cause),
        })
    )
  }
  const toggle = (tile: Tile) =>
    write(`change ${tile.name}`, tile.id, { on: !tile.on })

  const showTile = (id: string, trigger?: HTMLElement | null) => {
    returnFocusRef.current =
      trigger ?? (document.activeElement as HTMLElement | null)
    setOpenTileId(id)
  }

  const focusQueue = () => {
    setStripOpen(true)
    requestAnimationFrame(() => {
      const row =
        queueRef.current?.querySelector<HTMLElement>("[data-queue-row]")
      const root =
        queueRef.current?.querySelector<HTMLElement>("[data-queue-root]")
      ;(row ?? root)?.focus()
    })
  }

  const ready = status === "ready"
  const queueLabel =
    needYou.length > 0 ? `${needYou.length} need you` : "Nothing needs you"

  let tileArea
  if (status === "loading") tileArea = <LoadingState label="Loading tiles" />
  else if (status === "error") {
    tileArea = (
      <ErrorState
        error={error ?? new Error("Could not load tiles")}
        onRetry={onRetry}
      />
    )
  } else if (tiles.length === 0) {
    tileArea = (
      <EmptyState
        title="No tiles yet"
        description="Tiles you add show up here."
      />
    )
  } else {
    tileArea = (
      <TileBoard
