            className="mt-3 border-y @min-[768px]:order-last @min-[768px]:mt-0 @min-[768px]:flex @min-[768px]:w-80 @min-[768px]:shrink-0 @min-[768px]:flex-col @min-[768px]:border-t-0 @min-[768px]:border-b-0 @min-[768px]:border-l"
          >
