                <ChevronRightIcon aria-hidden className="size-4" />
              )}
              {queueLabel}
            </CollapsibleTrigger>
            <h2 className="hidden px-3 py-2 text-xs font-medium tracking-wide text-muted-foreground uppercase @min-[768px]:block">
